// JUDGMENT-CALL FORMULA, not brief-specified - flagged prominently, see the trigger node's own
// notes. Built from signals this repo's object model ACTUALLY HAS, not invented telemetry:
// tenure (longer without churning = healthier), Location count (more sites under contract =
// stickier), and contract tier (a proxy for account size/investment). Deliberately does NOT use
// 'usage' in the literal sense (call volume through the client's deployed AI receptionist/chatbot)
// - no telemetry pipeline from a deployed instance back into this CRM exists anywhere in this
// repo, so faking a usage signal from data that isn't real would be worse than omitting it. A real
// usage-based score needs that pipeline built first, not guessed at here.
const TENURE_MAX_POINTS = 40;
const TENURE_MAX_DAYS = 400; // ~13 months to hit the tenure cap
const LOCATION_MAX_POINTS = 30;
const LOCATION_POINTS_PER_SITE = 10; // caps at 3 Locations
const TIER_POINTS = { Gold: 10, Platinum: 20, Iridium: 30 };

function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.contracts)) return json.data.contracts;
  if (json && Array.isArray(json.contracts)) return json.contracts;
  return [];
}

const company = $('Fetch LiveClient Companies').item.json;
const contracts = $input.all().flatMap(asArray);
const contract = contracts[0]; // 'Active' filter should return at most one; first is a reasonable fallback if the filter query itself isn't honored (unconfirmed REST shape, same caveat as everywhere else).

const daysSinceLiveClient = company.liveClientSince
  ? (Date.now() - new Date(company.liveClientSince).getTime()) / 86400000
  : 0;
const tenureScore = Math.min(TENURE_MAX_POINTS, (daysSinceLiveClient / TENURE_MAX_DAYS) * TENURE_MAX_POINTS);

const locationCount = contract?.locationIds?.length || 0;
const locationScore = Math.min(LOCATION_MAX_POINTS, locationCount * LOCATION_POINTS_PER_SITE);

const tier = contract?.tier || null;
const tierScore = TIER_POINTS[tier] || 0;

const engagementScore = Math.round(tenureScore + locationScore + tierScore);

return [{ json: { companyId: company.id, engagementScore, currentTier: tier } }];
